const { Given, When, Then } = require('@cucumber/cucumber');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');

const ROOT = path.resolve(__dirname, '..', '..');

Given('the source file {string} exists', function (filePath) {
  const fullPath = path.join(ROOT, filePath);
  assert.ok(fs.existsSync(fullPath), `Source file not found: ${fullPath}`);
  this.sourceFile = fullPath;
});

When('I search for destructive element-rebuilding patterns', function () {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  this.foundPatterns = [];

  // Search for while-loop patterns that destroy and rebuild entire element trees
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.includes('while (todoListEl.firstChild)') || line.includes('while (todoCountEl.firstChild)')) {
      this.foundPatterns.push(line.trim());
    }
  }
});

Then('the pattern {string} should not appear in the source', function (pattern) {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes(pattern)) {
      assert.fail(`Pattern "${pattern}" found at line ${i + 1}: ${lines[i].trim()}`);
    }
  }
});

When('I read the source file', function () {
  const content = fs.readFileSync(this.sourceFile, 'utf8');
  this.sourceContent = content;
  this.sourceLines = content.split('\n');
});

Then('the source should contain a line setting {string} inside the render function', function (pattern) {
  const lines = this.sourceLines;
  // Find the render function body
  let inRender = false;
  let braceDepth = 0;
  let found = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim().startsWith('function render()') || line.trim().startsWith('function render (')) {
      inRender = true;
      braceDepth = 0;
    }
    if (inRender) {
      for (let j = 0; j < line.length; j++) {
        if (line[j] === '{') braceDepth++;
        if (line[j] === '}') braceDepth--;
      }
      if (line.includes(pattern)) {
        found = true;
        break;
      }
      if (braceDepth <= 0 && line.includes('function ')) {
        // Exited render for another function declaration at same level
        inRender = false;
      }
    }
  }
  assert.ok(found, `Pattern "${pattern}" not found inside render function`);
});

Then('the Enter keydown handler for edit input should call preventDefault before saveEdit', function () {
  const lines = this.sourceLines;
  // Find the keydown handler for edit input that handles ENTER_KEY
  // Look for a keydown event listener on todoListEl that has ENTER_KEY check
  let inEnterBranch = false;
  let inKeydownHandler = false;
  let braceDepth = 0;
  let hasPreventDefaultBeforeSaveEdit = false;
  let saveEditLine = -1;
  let preventDefaultLine = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Detect the keydown handler registration: addEventListener('keydown',
    if (line.includes("addEventListener('keydown'") && line.includes('function')) {
      inKeydownHandler = true;
      braceDepth = 0;
    }
    if (!inKeydownHandler) continue;

    for (let j = 0; j < line.length; j++) {
      if (line[j] === '{') braceDepth++;
      if (line[j] === '}') braceDepth--;
    }

    if (line.includes('ENTER_KEY')) {
      inEnterBranch = true;
    }

    if (inEnterBranch && line.includes('preventDefault')) {
      preventDefaultLine = i;
    }

    if (inEnterBranch && line.includes('saveEdit')) {
      saveEditLine = i;
    }

    if (braceDepth <= 0 && (line.includes('addEventListener') || line.includes('};'))) {
      // Check before exiting
      if (inEnterBranch && preventDefaultLine >= 0 && saveEditLine >= 0 && preventDefaultLine < saveEditLine) {
        hasPreventDefaultBeforeSaveEdit = true;
      }
      inKeydownHandler = false;
      inEnterBranch = false;
    }
  }

  // Also check the last handler if still open at end of file
  if (inEnterBranch && preventDefaultLine >= 0 && saveEditLine >= 0 && preventDefaultLine < saveEditLine) {
    hasPreventDefaultBeforeSaveEdit = true;
  }

  assert.ok(hasPreventDefaultBeforeSaveEdit,
    'Expected the ENTER_KEY branch of the keydown handler to call e.preventDefault() before saveEdit()');
});

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

/* ------------------------------------------------------------------ */
/*  Background / app load                                              */
/* ------------------------------------------------------------------ */

Given('the app is loaded', function () {
  // The Before hook in world.js already loads the app before every scenario.
  // This step is a no-op that anchors the Given clause.
});

/* ------------------------------------------------------------------ */
/*  New-todo input                                                     */
/* ------------------------------------------------------------------ */

When('I type {string} into the new-todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

/* ------------------------------------------------------------------ */
/*  Todo list assertions                                               */
/* ------------------------------------------------------------------ */

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then('the todo list contains {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} items, found ${items.length}`);
});

Then('the todo list contains {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} items, found ${items.length}`);
});

Then('the new item has title {string}', function (expectedTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  assert.ok(lastItem, 'No todo items found');
  const label = lastItem.querySelector('label');
  assert.ok(label, 'Last todo item has no label');
  assert.strictEqual(label.textContent.trim(), expectedTitle,

